	var i int32 = 0
	var k int32 = 0
	var h int32 = 0
	var v int32 = 0
	for i < n {
		k = 0
		for k < 9 {
			if k < 4 {
				v = ctPts(pdfdoc.PdPgMedia(pg, i, k))
			}
			if (k >= 4) && (k < 8) {
				v = ctPts(pdfdoc.PdPgCrop(pg, i, k-4))
			}
			if k == 8 {
				v = pdfdoc.PdPgRotate(pg, i)
			}
			v = v % 8388593
			if v < 0 {
				v += 8388593
			}
			h = ((h * 131) + v) % 8388593
			k += 1
		}
		i += 1
	}
	return h
