func ctVerify(file []byte, twin []byte, twinKnown int32, pages int32, digest int32, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, pg *port.Cells, out *port.Cells, ctr *port.Cells) int32 {
	// `file` is open (ar, dc, pg). A verdict: 0 all good; 1 page count; 2
	// geometry digest; 3 the catalog differs from the twin's; 4 the Info
	// dictionary does; 5 page 1's content does not begin `BT /F1 12 Tf`; 6 the
	// Info /Title is not `The Secret Title`; 7 too little was compared.
	var pdf *port.Src = port.SrcOfBlob(file)
	var ar2 *port.Cells = port.NewCells()
	var dc2 *port.Cells = port.NewCells()
	var a2 *port.Cells = port.NewCells()
	var b2 *port.Cells = port.NewCells()
	var st2 *port.Cells = port.NewCells()
	var ctr2 *port.Cells = port.NewCells()
	var hr int32 = 0
	var hi int32 = 0
	var hr2 int32 = 0
	var hi2 int32 = 0
	var t int32 = 0
	var con int32 = 0
	if pdfdoc.PdPgCount(pg) != pages {
		return 1
	}
	if ctDigest(pg) != digest {
		return 2
	}
	// Page 1's first content stream, decoded, begins with the operators we wrote.
	con = pdfdoc.PdPgContents(pg, 0)
	if con == 0 {
		return 5
	}
	if pdflex.PlKindOf(ar, con) != 8 {
		return 5
	}
	pdfdoc.PdStreamData(pdf, ar, dc, a, b, st, con, out)
	if port.CellsLen(out) < 12 {
		return 5
	}
	if port.CellsAt(out, 0) != 66 {
		return 5
	}
	if port.CellsAt(out, 1) != 84 {
		return 5
	}
	if port.CellsAt(out, 3) != 47 {
		return 5
	}
	if port.CellsAt(out, 4) != 70 {
		return 5
	}
	// The Info /Title, a string in an encrypted object.
	hi = pdfdoc.PdTrailerGet(ar, dc, pdfnames.PnInfo())
	if hi != 0 {
		hi = pdfdoc.PdResolve(pdf, ar, dc, a, b, st, hi)
		t = pdflex.PlDictGet(ar, hi, pdfnames.PnTitle())
		t = pdfdoc.PdResolve(pdf, ar, dc, a, b, st, t)
		if ctStrIs(ar, t, port.TextBlob("The Secret Title")) == 0 {
			return 6
		}
	}
	port.CellsDrop(ctr, 0)
	port.CellsPush(ctr, 0)
	port.CellsPush(ctr, 0)
	hr = ctHashRoot(pdf, ar, dc, a, b, st, out, ctr)
	hi = ctHashInfo(pdf, ar, dc, a, b, st, out, ctr)
	// The plain twin: the same content, never encrypted, never damaged.
	if twinKnown == 1 {
		port.CellsPush(ctr2, 0)
		port.CellsPush(ctr2, 0)
		pdfdoc.PdOpen(port.SrcOfBlob(twin), ar2, dc2, a2, b2, st2)
		hr2 = ctHashRoot(port.SrcOfBlob(twin), ar2, dc2, a2, b2, st2, out, ctr2)
		hi2 = ctHashInfo(port.SrcOfBlob(twin), ar2, dc2, a2, b2, st2, out, ctr2)
		if hr != hr2 {
			return 3
		}
		if (hi != 0) && (hi != hi2) {
			return 4
		}
		if port.CellsAt(ctr, 0) < 60 {
			return 7
		}
		if port.CellsAt(ctr, 1) < 300 {
			return 7
		}
	}
	return 0
}

func TestEveryRowOpensOrFailsAsNamedAndDecryptsToItsTwin(emonT *testing.T) {
	// Row: file, password, status, pages, digest, twin.
	var f []byte = port.TestFile("pdf/p3.txt")
	var ar *port.Cells = port.NewCells()
	var dc *port.Cells = port.NewCells()
	var a *port.Cells = port.NewCells()
	var b *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	var pg *port.Cells = port.NewCells()
	var out *port.Cells = port.NewCells()
	var ctr *port.Cells = port.NewCells()
	var n int32 = port.BlobLen(f)
	var pos int32 = 0
	var line int32 = 0
	var rows int32 = 0
	var opened int32 = 0
	var e int32 = 0
	var s0 int32 = 0
	var s1 int32 = 0
	var s2 int32 = 0
	var s3 int32 = 0
	var s4 int32 = 0
	var status int32 = 0
	for pos < n {
		line += 1
		e = ctNl(f, pos)
		if (pos < e) && (port.BlobU8(f, pos) != 35) {
			rows += 1
			s0 = ctTab(f, pos, e)
			s1 = ctTab(f, s0+1, e)
			s2 = ctTab(f, s1+1, e)
			s3 = ctTab(f, s2+1, e)
			s4 = ctTab(f, s3+1, e)
			var t *strings.Builder = port.NewText()
			var file []byte = port.TestFileSpan(f, pos, s0)
			status = ctOpen(file, f, s0+1, s1, ar, dc, a, b, st, pg)
			pdfdoc.PdStatusEmitName(t, status)
			port.AssertTextSpan(emonT, t, f, s1+1, s2, "status", line)
			if status == 0 {
				opened += 1
				if ctDash(f, s4+1, e) == 1 {
					port.AssertEqAt(emonT, ctVerify(file, file, 0, ctDec(f, s2+1, s3), ctDec(f, s3+1, s4), ar, dc, a, b, st, pg, out, ctr), 0, "pages, geometry, content, title", line)
				} else {
					port.AssertEqAt(emonT, ctVerify(file, port.TestFileSpan(f, s4+1, e), 1, ctDec(f, s2+1, s3), ctDec(f, s3+1, s4), ar, dc, a, b, st, pg, out, ctr), 0, "pages, geometry, content, title, equal to the twin", line)
				}
			}
		}
		pos = e + 1
	}
	port.AssertThat(emonT, rows > 70, "the rows were read")
	port.AssertThat(emonT, opened > 50, "most rows open")
}

func ctWindowIn(c *port.Cells, rows []byte, ps int32, pe int32) int32 {
	// 1 when the first (up to 8) bytes of the password rows[ps, pe) occur, in
	// a row, among the cells of c.
	var w int32 = pe - ps
	var i int32 = 0
	var k int32 = 0
	var same int32 = 0
	if w > 8 {
		w = 8
	}
	if w < 4 {
		return 0
	}
	for (i + w) <= port.CellsLen(c) {
		same = 1
		k = 0
		for (same == 1) && (k < w) {
			if port.CellsAt(c, i+k) != port.BlobU8(rows, ps+k) {
				same = 0
			}
			k += 1
		}
		if same == 1 {
			return 1
		}
		i += 1
	}
	return 0
}

func TestAPasswordIsNotLeftInTheArenaTheDocumentOrTheScratch(emonT *testing.T) {
	// D058: the password rides with the input and is never written down. After
	// a complete open, the page walk and a read of page 1's content, none of
	// the cells kin holds contains it (its first bytes: 8 at most).
	var f []byte = port.TestFile("pdf/p3.txt")
	var ar *port.Cells = port.NewCells()
	var dc *port.Cells = port.NewCells()
	var a *port.Cells = port.NewCells()
	var b *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	var pg *port.Cells = port.NewCells()
	var out *port.Cells = port.NewCells()
	var n int32 = port.BlobLen(f)
	var pos int32 = 0
	var line int32 = 0
	var checked int32 = 0
	var e int32 = 0
	var s0 int32 = 0
	var s1 int32 = 0
	var status int32 = 0
	var con int32 = 0
	for pos < n {
		line += 1
		e = ctNl(f, pos)
		if (pos < e) && (port.BlobU8(f, pos) != 35) {
			s0 = ctTab(f, pos, e)
			s1 = ctTab(f, s0+1, e)
			if ctDash(f, s0+1, s1) == 0 {
				var file []byte = port.TestFileSpan(f, pos, s0)
				status = ctOpen(file, f, s0+1, s1, ar, dc, a, b, st, pg)
				if status == 0 {
					con = pdfdoc.PdPgContents(pg, 0)
					if con != 0 {
						pdfdoc.PdStreamData(port.SrcOfBlob(file), ar, dc, a, b, st, con, out)
					}
				}
				checked += 1
				port.AssertEqAt(emonT, ctWindowIn(ar, f, s0+1, s1), 0, "not in the arena", line)
				port.AssertEqAt(emonT, ctWindowIn(dc, f, s0+1, s1), 0, "not in the document", line)
				port.AssertEqAt(emonT, ctWindowIn(a, f, s0+1, s1), 0, "not in scratch a", line)
				port.AssertEqAt(emonT, ctWindowIn(b, f, s0+1, s1), 0, "not in scratch b", line)
				port.AssertEqAt(emonT, ctWindowIn(st, f, s0+1, s1), 0, "not in scratch st", line)
				port.AssertEqAt(emonT, ctWindowIn(pg, f, s0+1, s1), 0, "not in the page table", line)
			}
		}
		pos = e + 1
	}
	port.AssertThat(emonT, checked > 40, "rows with a password were checked")
}

func ctDiff(x *port.Cells, y *port.Cells) int32 {
	var n int32 = port.CellsLen(x)
	var i int32 = 0
	if n != port.CellsLen(y) {
		return -2
	}
	for i < n {
		if port.CellsAt(x, i) != port.CellsAt(y, i) {
			return i
		}
		i += 1
	}
	return -1
}

func ctSameAsync(file []byte, rows []byte, ps int32, pe int32, chunk int32) int32 {
	// Open in memory and through an async source of `chunk`-byte chunks, with
	// the password: a verdict, 0 for the same. 1 the status differs; 2, 3, 4 the
	// arena, document or page table; 5 an attempt that missed reported a status
	// other than need-bytes; 6 it reported a warning the real run lacks; 7 more
	// than 24 rounds (FETCH_ROUNDS).
	var ar1 *port.Cells = port.NewCells()
	var dc1 *port.Cells = port.NewCells()
	var a1 *port.Cells = port.NewCells()
	var b1 *port.Cells = port.NewCells()
	var st1 *port.Cells = port.NewCells()
	var pg1 *port.Cells = port.NewCells()
	var ar2 *port.Cells = port.NewCells()
	var dc2 *port.Cells = port.NewCells()
	var a2 *port.Cells = port.NewCells()
	var b2 *port.Cells = port.NewCells()
	var st2 *port.Cells = port.NewCells()
	var pg2 *port.Cells = port.NewCells()
	var base *port.Src = port.SrcChunked(file, chunk, 0)
	var s1 int32 = ctOpen(file, rows, ps, pe, ar1, dc1, a1, b1, st1, pg1)
	var wf int32 = pdfdoc.PdWarn(dc1)
	var round int32 = 0
	var more int32 = 1
	var s2 int32 = 0
	var w int32 = 0
	var badstatus int32 = 0
	var badwarn int32 = 0
	for more == 1 {
		var v *port.Src = port.SrcView(base)
		if ctDash(rows, ps, pe) == 1 {
			s2 = pdfdoc.PdOpen(v, ar2, dc2, a2, b2, st2)
		} else {
			s2 = pdfdoc.PdOpenPw(v, port.SrcOfBlob(port.SrcSlice(port.SrcOfBlob(rows), ps, pe)), ar2, dc2, a2, b2, st2)
		}
		port.CellsDrop(pg2, 0)
		if s2 == 0 {
			pdfdoc.PdPages(v, ar2, dc2, a2, b2, st2, pg2)
		}
		if pdfsrc.PsMissed(v) {
			w = pdfdoc.PdWarn(dc2)
			if (s2 != 0) && (s2 != 7) {
				badstatus = 1
			}
			if (w | wf) != wf {
				badwarn = 1
			}
			port.SrcCtl(base, 0, round)
			round += 1
			if round > 40 {
				more = 0
			}
		} else {
			more = 0
		}
	}
	if s1 != s2 {
		return 1
	}
	if badstatus == 1 {
		return 5
	}
	if badwarn == 1 {
		return 6
	}
	if round > 24 {
		return 7
	}
	if ctDiff(ar1, ar2) != -1 {
		return 2
	}
	if ctDiff(dc1, dc2) != -1 {
		return 3
	}
	if ctDiff(pg1, pg2) != -1 {
		return 4
	}
	return 0
}

func TestEveryRowIsTheSameThroughAnAsyncSourceOf512ByteChunks(emonT *testing.T) {
	// D058 and D075 over repair and decryption: a scan of the whole file and the
	// key derivation happen on a source that misses, and what is kept is the
	// in-memory run cell for cell; no miss ever becomes a status, a warning,
	// or a wrong password.
	var f []byte = port.TestFile("pdf/p3.txt")
	var n int32 = port.BlobLen(f)
	var pos int32 = 0
	var line int32 = 0
	var rows int32 = 0
	var e int32 = 0
	var s0 int32 = 0
	var s1 int32 = 0
	for pos < n {
		line += 1
		e = ctNl(f, pos)
		if (pos < e) && (port.BlobU8(f, pos) != 35) {
			rows += 1
			s0 = ctTab(f, pos, e)
			s1 = ctTab(f, s0+1, e)
			port.AssertEqAt(emonT, ctSameAsync(port.TestFileSpan(f, pos, s0), f, s0+1, s1, 512), 0, "async equals in-memory", line)
		}
		pos = e + 1
	}
	port.AssertThat(emonT, rows > 70, "the rows were read")
}

func TestARepairedFileIsTheSameThroughAnAsyncSourceOf64ByteChunks(emonT *testing.T) {
	var f []byte = port.TestFile("pdf/p3.txt")
	var n int32 = port.BlobLen(f)
	var pos int32 = 0
	var line int32 = 0
	var rows int32 = 0
	var e int32 = 0
	var s0 int32 = 0
	var s1 int32 = 0
	for pos < n {
		line += 1
		e = ctNl(f, pos)
		if (pos < e) && (port.BlobU8(f, pos) != 35) {
			s0 = ctTab(f, pos, e)
			s1 = ctTab(f, s0+1, e)
			if port.BlobU8(f, pos+7) == 114 {
				rows += 1
				port.AssertEqAt(emonT, ctSameAsync(port.TestFileSpan(f, pos, s0), f, s0+1, s1, 64), 0, "async equals in-memory", line)
			}
		}
		pos = e + 1
	}
	// `pdf/p3/repair-...`: the eighth byte of the row is the `r`.
	port.AssertThat(emonT, rows > 10, "the repair rows were read")
}

func ctInfo(file []byte, which int32) int32 {
	// Open without a password (the empty user password is tried) and answer
	// 1 the pd-status, 2 `pd-encrypted`, 3 the warning bits.
	var ar *port.Cells = port.NewCells()
	var dc *port.Cells = port.NewCells()
	var a *port.Cells = port.NewCells()
	var b *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	var status int32 = pdfdoc.PdOpen(port.SrcOfBlob(file), ar, dc, a, b, st)
	if which == 1 {
		return status
	}
	if which == 2 {
		return pdfdoc.PdEncrypted(dc)
	}
	return pdfdoc.PdWarn(dc)
}

func TestRepairIsNotedAndOnlyWhereItHappened(emonT *testing.T) {
	port.AssertEq(emonT, ctInfo(port.TestFile("pdf/p3/plain.pdf"), 3), 0, "an undamaged file has no warning")
	port.AssertEq(emonT, ctInfo(port.TestFile("pdf/p3/repair-startxref-wrong.pdf"), 3), 512, "the table was rebuilt")
	port.AssertEq(emonT, ctInfo(port.TestFile("pdf/p3/repair-startxref-past-end.pdf"), 3), 512, "a startxref past the end")
	port.AssertEq(emonT, ctInfo(port.TestFile("pdf/p3/repair-cut-before-xref.pdf"), 3), 512, "no startxref at all")
	port.AssertEq(emonT, ctInfo(port.TestFile("pdf/p3/repair-offsets-shifted.pdf"), 1), 0, "shifted offsets: it opens")
	port.AssertEq(emonT, ctInfo(port.TestFile("pdf/p3/crypt-aes-128-empty.pdf"), 3), 0, "decryption is not damage")
}

func TestAnEncryptedFileSaysSoWhetherOrNotItOpens(emonT *testing.T) {
	port.AssertEq(emonT, ctInfo(port.TestFile("pdf/p3/plain.pdf"), 2), 0, "a plain file is not encrypted")
	port.AssertEq(emonT, ctInfo(port.TestFile("pdf/p3/crypt-aes-128-empty.pdf"), 2), 1, "opened by the empty password")
	port.AssertEq(emonT, ctInfo(port.TestFile("pdf/p3/crypt-aes-128-user.pdf"), 2), 1, "locked")
	port.AssertEq(emonT, ctInfo(port.TestFile("pdf/p3/crypt-aes-128-user.pdf"), 1), 8, "password-required is status 8")
	port.AssertEq(emonT, ctInfo(port.TestFile("pdf/p3/unsupported-pubsec.pdf"), 1), 10, "encryption-unsupported is status 10")
}

func TestTheWrongPasswordIsIncorrectAndNoPasswordIsRequired(emonT *testing.T) {
	// Three errors, distinct from each other and from a damaged file (D040).
	var ar *port.Cells = port.NewCells()
	var dc *port.Cells = port.NewCells()
	var a *port.Cells = port.NewCells()
	var b *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	var locked []byte = port.TestFile("pdf/p3/crypt-aes-256-r6-user.pdf")
	port.AssertEq(emonT, pdfdoc.PdOpen(port.SrcOfBlob(locked), ar, dc, a, b, st), 8, "none supplied: password-required")
	port.AssertEq(emonT, pdfdoc.PdOpenPw(port.SrcOfBlob(locked), port.SrcOfBlob(port.TextBlob("wrong-password")), ar, dc, a, b, st), 9, "a wrong one: password-incorrect")
	port.AssertEq(emonT, pdfdoc.PdOpenPw(port.SrcOfBlob(locked), port.SrcOfBlob(port.TextBlob("user-secret")), ar, dc, a, b, st), 0, "the user password opens it")
	port.AssertEq(emonT, pdfdoc.PdOpenPw(port.SrcOfBlob(locked), port.SrcOfBlob(port.TextBlob("owner-secret")), ar, dc, a, b, st), 0, "and so does the owner password")
	port.AssertEq(emonT, pdfdoc.PdOpenPw(port.SrcOfBlob(locked), port.SrcOfBlob(port.TextBlob("")), ar, dc, a, b, st), 8, "an empty password is none supplied")
	port.AssertEq(emonT, pdfdoc.PdOpen(port.SrcOfBlob(port.TestFile("pdf/p3/crypt-rc4-40-user.pdf")), ar, dc, a, b, st), 8, "RC4-40: password-required")
	port.AssertEq(emonT, pdfdoc.PdOpenPw(port.SrcOfBlob(port.TestFile("pdf/p3/crypt-rc4-40-user.pdf")), port.SrcOfBlob(port.TextBlob("owner-secret")), ar, dc, a, b, st), 0, "RC4-40: the owner password recovers the user password from /O")
}

func ctSurvive(file []byte, rows []byte, ps int32, pe int32, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, pg *port.Cells, out *port.Cells) int32 {
	// Open (with the password), list the pages and decode every stream the
	// cross-reference names: none of it may fault. Answers the pd-status.
	var status int32 = ctOpen(file, rows, ps, pe, ar, dc, a, b, st, pg)
	var pdf *port.Src = port.SrcOfBlob(file)
	var i int32 = 1
	var h int32 = 0
	if status == 0 {
		for i < pdfdoc.PdObjectCount(dc) {
			h = pdfdoc.PdGet(pdf, ar, dc, a, b, st, i)
			if h != 0 {
				if pdflex.PlKindOf(ar, h) == 8 {
					pdfdoc.PdStreamData(pdf, ar, dc, a, b, st, h, out)
				}
			}
			i += 1
		}
	}
	return status
}

func ctFuzz(f []byte, pw []byte, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, pg *port.Cells, out *port.Cells, cut *port.Cells, rng *port.Cells) int32 {
	// Every 37th truncation of f and sixty copies with three random bytes
	// replaced, each opened with the password `pw` and read through: none may
	// fault. Answers how many were tried.
	var n int32 = port.BlobLen(f)
	var pn int32 = port.BlobLen(pw)
	var k int32 = 0
	var j int32 = 0
	var r int32 = 0
	var at int32 = 0
	var total int32 = 0
	for k <= n {
		port.CellsDrop(cut, 0)
		j = 0
		for j < k {
			port.CellsPush(cut, port.BlobU8(f, j))
			j += 1
		}
		ctSurvive(port.CellsBlob(cut), pw, 0, pn, ar, dc, a, b, st, pg, out)
		total += 1
		k += 37
	}
	for r < 60 {
		port.CellsDrop(cut, 0)
		j = 0
		for j < n {
			port.CellsPush(cut, port.BlobU8(f, j))
			j += 1
		}
		j = 0
		for j < 3 {
			at = splitmix.SmBelow(rng, n)
			port.CellsSet(cut, at, splitmix.SmBelow(rng, 256))
			j += 1
		}
		ctSurvive(port.CellsBlob(cut), pw, 0, pn, ar, dc, a, b, st, pg, out)
		total += 1
		r += 1
	}
	return total
}

func TestADamagedEncryptedFileNeverFaults(emonT *testing.T) {
	// Truncations and random corruptions (SplitMix: every target damages the
	// same bytes) of an RC4, an AES-128, an AES-256 and an AES-256 object-stream
	// file, with their passwords: a flipped byte in the /Encrypt dictionary, the
	// cipher text, the object stream or the table is an error or a different
	// answer, never a fault, and the repair scan that follows it terminates.
	var ar *port.Cells = port.NewCells()
	var dc *port.Cells = port.NewCells()
	var a *port.Cells = port.NewCells()
	var b *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	var pg *port.Cells = port.NewCells()
	var out *port.Cells = port.NewCells()
	var cut *port.Cells = port.NewCells()
	var rng *port.Cells = port.NewCells()
	var total int32 = 0
	splitmix.SmSeed(rng, int64(11))
	total += ctFuzz(port.TestFile("pdf/p3/crypt-rc4-128-user.pdf"), port.TextBlob("user-secret"), ar, dc, a, b, st, pg, out, cut, rng)
	total += ctFuzz(port.TestFile("pdf/p3/crypt-aes-128-user.pdf"), port.TextBlob("user-secret"), ar, dc, a, b, st, pg, out, cut, rng)
	total += ctFuzz(port.TestFile("pdf/p3/crypt-aes-256-r6-user.pdf"), port.TextBlob("user-secret"), ar, dc, a, b, st, pg, out, cut, rng)
	total += ctFuzz(port.TestFile("pdf/p3/crypt-aes-128-objstm-user.pdf"), port.TextBlob("user-secret"), ar, dc, a, b, st, pg, out, cut, rng)
	port.AssertThat(emonT, total > 200, "the damaged files were opened")
}
